CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, name text NOT NULL, permissions jsonb NOT NULL DEFAULT '[]', UNIQUE (organization_id, name), UNIQUE (organization_id, id));
CREATE TABLE memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users ON DELETE RESTRICT, role_id uuid NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (organization_id, role_id) REFERENCES roles (organization_id, id) ON DELETE RESTRICT, UNIQUE (organization_id, user_id));
CREATE TABLE branches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, name text NOT NULL, code text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, id), UNIQUE (organization_id, code));
CREATE TABLE warehouses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, branch_id uuid NOT NULL, name text NOT NULL, code text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (organization_id, branch_id) REFERENCES branches (organization_id, id) ON DELETE RESTRICT, UNIQUE (organization_id, id), UNIQUE (organization_id, code));
CREATE TABLE registered_devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users ON DELETE RESTRICT, device_name text NOT NULL, platform text NOT NULL CHECK (platform IN ('ios','android')), revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, id));
CREATE TABLE product_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, name text NOT NULL, parent_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (organization_id, parent_id) REFERENCES product_categories (organization_id, id) ON DELETE RESTRICT, UNIQUE (organization_id, id), UNIQUE (organization_id, name));
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, category_id uuid, sku text NOT NULL, name text NOT NULL, product_type text NOT NULL DEFAULT 'standard' CHECK (product_type IN ('standard','fabric','garment')), active boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, FOREIGN KEY (organization_id, category_id) REFERENCES product_categories (organization_id, id) ON DELETE RESTRICT, UNIQUE (organization_id, id), UNIQUE (organization_id, sku));
CREATE TABLE units (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, UNIQUE (organization_id, id), UNIQUE (organization_id, code));
CREATE TABLE unit_conversions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, from_unit_id uuid NOT NULL, to_unit_id uuid NOT NULL, factor numeric(18,6) NOT NULL CHECK (factor > 0), FOREIGN KEY (organization_id, from_unit_id) REFERENCES units (organization_id, id) ON DELETE RESTRICT, FOREIGN KEY (organization_id, to_unit_id) REFERENCES units (organization_id, id) ON DELETE RESTRICT, UNIQUE (organization_id, from_unit_id, to_unit_id));
CREATE TABLE product_barcodes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, product_id uuid NOT NULL, barcode text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (organization_id, product_id) REFERENCES products (organization_id, id) ON DELETE CASCADE, UNIQUE (organization_id, barcode));
CREATE TABLE sync_operations (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, device_id uuid NOT NULL, operation_type text NOT NULL, entity_id uuid NOT NULL, schema_version integer NOT NULL CHECK (schema_version > 0), payload jsonb NOT NULL, created_at timestamptz NOT NULL, acknowledged_at timestamptz, FOREIGN KEY (organization_id, device_id) REFERENCES registered_devices (organization_id, id) ON DELETE RESTRICT, UNIQUE (organization_id, id));
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, actor_user_id uuid REFERENCES users ON DELETE SET NULL, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX memberships_user_idx ON memberships(user_id, organization_id) WHERE active;
CREATE INDEX warehouses_branch_idx ON warehouses(organization_id, branch_id);
CREATE INDEX products_category_idx ON products(organization_id, category_id) WHERE deleted_at IS NULL;
CREATE INDEX sync_pending_idx ON sync_operations(organization_id, created_at) WHERE acknowledged_at IS NULL;
CREATE INDEX audit_org_time_idx ON audit_events(organization_id, created_at DESC);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['roles','memberships','branches','warehouses','registered_devices','product_categories','products','units','unit_conversions','product_barcodes','sync_operations','audit_events'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (organization_id = nullif(current_setting(''app.organization_id'', true), '''')::uuid) WITH CHECK (organization_id = nullif(current_setting(''app.organization_id'', true), '''')::uuid)', t); END LOOP; END $$;
